'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Evaluates the complementary error function for a single-precision floating-point number.
*
* @private
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var y = erfcf( 0.0 );
* // returns 1.0
*
* @example
* var y = erfcf( 1.0 );
* // returns ~0.1573
*
* @example
* var y = erfcf( -1.0 );
* // returns ~1.8427
*
* @example
* var y = erfcf( NaN );
* // returns NaN
*/
function erfcf( x )
{
	return addon( x );
}


// EXPORTS //

module.exports = erfcf;
